	/*
     * @param	event CreateAuthorizationEvent
     */
    @EventHandler( payloadType=CreateAuthorizationEvent.class )
    public void handle( CreateAuthorizationEvent event) {
	    LOGGER.info("handling CreateAuthorizationEvent - " + event );
	    Authorization entity = new Authorization();
            entity.setAuthorizationId( event.getAuthorizationId() );
            entity.setAuthNumber( event.getAuthNumber() );
            entity.setRequestedService( event.getRequestedService() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllAuthorization( entity );
    }

    /*
     * @param	event UpdateAuthorizationEvent
     */
    @EventHandler( payloadType=UpdateAuthorizationEvent.class )
    public void handle( UpdateAuthorizationEvent event) {
    	LOGGER.info("handling UpdateAuthorizationEvent - " + event );
    	
	    Authorization entity = new Authorization();
            entity.setAuthorizationId( event.getAuthorizationId() );
            entity.setAuthNumber( event.getAuthNumber() );
            entity.setRequestedService( event.getRequestedService() );
            entity.setCoverage( event.getCoverage() );
            entity.setOrder( event.getOrder() );
            entity.setStatus( event.getStatus() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindAuthorization( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllAuthorization( entity );        
    }
    
