    /**
     * Method to retrieve the Authorization via an AuthorizationPrimaryKey.
     * @param 	id Long
     * @return 	Authorization
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Authorization handle( FindAuthorizationQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getAuthorizationId() );
    }
    
    /**
     * Method to retrieve a collection of all Authorizations
     *
     * @param	query	FindAllAuthorizationQuery 
     * @return 	List<Authorization> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Authorization> handle( FindAllAuthorizationQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindAuthorization,
 * but only if the id matches
 *
 * @param		entity	Authorization
 */
	protected void emitFindAuthorization( Authorization entity ) {
		LOGGER.info("handling emitFindAuthorization" );
		
	    queryUpdateEmitter.emit(FindAuthorizationQuery.class,
	                            query -> query.getFilter().getAuthorizationId().equals(entity.getAuthorizationId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllAuthorization
	 * 
	 * @param		entity	Authorization
	 */
	protected void emitFindAllAuthorization( Authorization entity ) {
		LOGGER.info("handling emitFindAllAuthorization" );
		
	    queryUpdateEmitter.emit(FindAllAuthorizationQuery.class,
	                            query -> true,
	                            entity);
	}

